package com.bank.txreach.service;

import java.util.logging.Logger;

// Greedy reachability: extend the farthest reachable index each step.
public class TransferReachService {
    private static final Logger log = Logger.getLogger(TransferReachService.class.getName());

    public boolean canReachFinal(int[] limits) {
        int n = limits.length;
        int farthest = 0;                                  // farthest account reachable so far
        for (int i = 0; i < n; i++) {
            if (i > farthest) {                            // this account is unreachable
                log.warning(() -> "Stuck: cannot reach account index beyond the farthest reach");
                return false;
            }
            farthest = Math.max(farthest, i + limits[i]);  // extend the reach
            if (farthest >= n - 1) {
                log.info(() -> "Final settlement account is reachable");
                return true;                               // final account covered
            }
        }
        return true;
    }
}
