package com.bank.txreach;

import com.bank.txreach.service.TransferReachService;
import java.util.logging.Logger;

public class TransferReachApplication {
    private static final Logger log = Logger.getLogger(TransferReachApplication.class.getName());

    public static void main(String[] args) {
        TransferReachService service = new TransferReachService();
        int[] limits = {2, 3, 1, 1, 4};                    // forwarding limit per account
        boolean ok = service.canReachFinal(limits);
        log.info(() -> "Can reach final settlement account = " + ok);
    }
}
